\begin{remark}[``PDE'' as Singular and Plural]
\label{rem:pde-abbreviation}
\dcref{ch1:1.1-rem-1}
\group{PDE Basics}
``PDE'' abbreviates both ``partial differential equation'' and ``partial differential equations''. $\square$
\end{remark}

